window.STUDY_DATA = {"groups": {"w1": {"name": "Week 1", "title": "Usability & design", "description": "Goals, design principles, human error and user experience.", "kind": "lecture"}, "w2": {"name": "Week 2", "title": "Humans & cognition", "description": "Mental models, action cycle, perception, attention and memory.", "kind": "lecture"}, "w3": {"name": "Week 3", "title": "Input & mobile", "description": "Devices, sensors, virtual reality and mobile constraints.", "kind": "lecture"}, "w4": {"name": "Week 4", "title": "Requirements & research", "description": "Users, research methods, use cases and task models.", "kind": "lecture"}, "project": {"name": "Project", "title": "Assignment & your idea", "description": "The walkthrough brief and your proposed nutrition companion.", "kind": "project"}, "extra": {"name": "Other professor", "title": "Supplemental midterm practice", "description": "Topics from the photos; not evidence of Andriy’s exam coverage.", "kind": "supplemental"}, "context": {"name": "Background", "title": "Slides marked “Not on test”", "description": "Optional context from Week 2, excluded from lecture drills.", "kind": "background"}}, "questions": [{"id": "w1-m01", "type": "mcq", "group": "w1", "prompt": "Which sequence best represents iterative interface design?", "options": ["Design, prototype, evaluate, revise", "Specify, code, release, stop", "Choose colours, advertise, release, survey", "Train users, release, then gather requirements"], "correct": 0, "explanation": "Evaluation informs revisions throughout design.", "source": "Week 1 · PDF pp. 5–6", "topic": "Design process"}, {"id": "w1-m02", "type": "mcq", "group": "w1", "prompt": "A system supports every needed function, but users cannot operate it. Which distinction matters?", "options": ["Utility versus usability", "Safety versus hardware speed", "Memorability versus data storage", "UX versus screen resolution"], "correct": 0, "explanation": "A function can exist without being usable.", "source": "Week 1 · PDF pp. 73, 78", "topic": "Usability goals"}, {"id": "w1-m03", "type": "mcq", "group": "w1", "prompt": "Users finish a task correctly but spend unnecessary time doing it. Which goal needs work?", "options": ["Efficiency", "Utility", "Effectiveness", "Memorability"], "correct": 0, "explanation": "Efficiency concerns the effort and time required for successful use.", "source": "Week 1 · PDF p. 73", "topic": "Usability goals"}, {"id": "w1-m04", "type": "mcq", "group": "w1", "prompt": "Which measure most directly concerns effectiveness?", "options": ["Whether the intended task is completed correctly", "How attractive the interface looks", "How many optional features exist", "How recently the user last visited"], "correct": 0, "explanation": "Effectiveness concerns achieving the intended goal.", "source": "Week 1 · PDF p. 73", "topic": "Usability goals"}, {"id": "w1-m05", "type": "mcq", "group": "w1", "prompt": "An occasional user returns after months and still knows how to proceed. Which goal is supported?", "options": ["Memorability", "Utility", "System throughput", "Novelty"], "correct": 0, "explanation": "Memorability concerns remembering how to use a system after time away.", "source": "Week 1 · PDF p. 73", "topic": "Usability goals"}, {"id": "w1-m06", "type": "mcq", "group": "w1", "prompt": "A first-time user learns the booking process quickly. Which goal is illustrated?", "options": ["Learnability", "Memorability", "Raw performance", "Feature completeness"], "correct": 0, "explanation": "Learnability concerns acquiring the ability to use the system.", "source": "Week 1 · PDF p. 73", "topic": "Usability goals"}, {"id": "w1-m07", "type": "mcq", "group": "w1", "prompt": "A payment tool cannot issue refunds, though users need them. Which goal is lacking?", "options": ["Utility", "Memorability", "Visual similarity", "Feedback latency"], "correct": 0, "explanation": "Utility concerns whether needed functions are available.", "source": "Week 1 · PDF p. 73", "topic": "Usability goals"}, {"id": "w1-m08", "type": "mcq", "group": "w1", "prompt": "Why should designers account for distraction and fatigue?", "options": ["They are predictable human limitations that design must accommodate", "They make user research unnecessary", "They can always be eliminated by training", "They prove that users are responsible for all failures"], "correct": 0, "explanation": "The lecture challenges blaming users for failures encouraged by design.", "source": "Week 1 · PDF pp. 42–43, 59", "topic": "Human error"}, {"id": "w1-m09", "type": "mcq", "group": "w1", "prompt": "Who is central to user-centred design?", "options": ["Actual users and evidence about their needs", "Only the most experienced developer", "Only the purchasing department", "Only the visual designer’s intuition"], "correct": 0, "explanation": "User-centred design incorporates users into development.", "source": "Week 1 · PDF p. 63", "topic": "Design process"}, {"id": "w1-m10", "type": "mcq", "group": "w1", "prompt": "What is an affordance?", "options": ["A possible action arising from an object–person relationship", "A decorative theme shared across screens", "A message displayed after an error", "A mandatory sequence of menu items"], "correct": 0, "explanation": "A handle affords grasping; a knob affords turning.", "source": "Week 1 · PDF p. 80", "topic": "Design principles"}, {"id": "w1-m11", "type": "mcq", "group": "w1", "prompt": "A graphical button looks clickable because users recognize its styling. What best describes this?", "options": ["A perceived affordance using learned conventions", "A physical spring-return mechanism", "A system performance requirement", "A guarantee of universal cultural understanding"], "correct": 0, "explanation": "Virtual interfaces often rely on perceived affordances and conventions.", "source": "Week 1 · PDF p. 81", "topic": "Design principles"}, {"id": "w1-m12", "type": "mcq", "group": "w1", "prompt": "Stove controls arranged to match burner positions mainly improve what?", "options": ["Mapping", "User anonymity", "Memory capacity", "Feature count"], "correct": 0, "explanation": "Spatial correspondence clarifies which control affects which burner.", "source": "Week 1 · PDF p. 87", "topic": "Design principles"}, {"id": "w1-m13", "type": "mcq", "group": "w1", "prompt": "After Save, a visible message says “Saved.” Which principle is demonstrated?", "options": ["Feedback", "Utility", "Physical affordance", "Cultural localization"], "correct": 0, "explanation": "Feedback communicates the result of an action.", "source": "Week 1 · PDF p. 88", "topic": "Design principles"}, {"id": "w1-m14", "type": "mcq", "group": "w1", "prompt": "A crucial function is hidden behind an unfamiliar icon. Which issue is most direct?", "options": ["Visibility", "Calorie accuracy", "Motor neutral position", "Power consumption"], "correct": 0, "explanation": "Users need to discover relevant controls and actions.", "source": "Week 1 · PDF p. 91", "topic": "Design principles"}, {"id": "w1-m15", "type": "mcq", "group": "w1", "prompt": "Disabling an impossible date choice is an example of what?", "options": ["A constraint", "A positive transfer effect", "A colour model", "A conceptual mismatch alone"], "correct": 0, "explanation": "Constraints restrict actions and can prevent invalid choices.", "source": "Week 1 · PDF p. 96", "topic": "Design principles"}, {"id": "w1-m16", "type": "mcq", "group": "w1", "prompt": "Why use similar labels and behaviours for similar tasks?", "options": ["To reduce learning demands through consistency", "To make every function visually identical", "To remove the need for feedback", "To prevent experienced users using shortcuts"], "correct": 0, "explanation": "Consistency supports learning and predictable use.", "source": "Week 1 · PDF pp. 97–98", "topic": "Design principles"}, {"id": "w1-m17", "type": "mcq", "group": "w1", "prompt": "A familiar shortcut performs the same action in a new editor. What is this?", "options": ["Positive transfer", "Negative transfer", "Change blindness", "A physical constraint"], "correct": 0, "explanation": "Prior experience helps with the current task.", "source": "Week 1 · PDF pp. 92–93; Week 2 p. 46", "topic": "Transfer"}, {"id": "w1-m18", "type": "mcq", "group": "w1", "prompt": "A familiar aircraft-control location triggers a different action in another aircraft. What risk does this illustrate?", "options": ["Negative transfer", "Improved recognition", "Successful annotation", "Increased utility"], "correct": 0, "explanation": "An old learned response can interfere in a new context.", "source": "Week 1 · PDF pp. 50–51, 92", "topic": "Transfer"}, {"id": "w1-m19", "type": "mcq", "group": "w1", "prompt": "Which statement best describes user experience?", "options": ["It includes feelings and the broader interaction with a product and service", "It is identical to the number of features", "It can be guaranteed for every user by selecting colours", "It concerns only task-completion speed"], "correct": 0, "explanation": "UX includes satisfaction, emotion, and the wider experience.", "source": "Week 1 · PDF pp. 70–71, 76", "topic": "User experience"}, {"id": "w1-m20", "type": "mcq", "group": "w1", "prompt": "Which is a desirable experience goal named in the lecture?", "options": ["Engagement", "Patronizing behaviour", "Frustration", "Boredom"], "correct": 0, "explanation": "Engagement is among the desirable UX goals.", "source": "Week 1 · PDF p. 76", "topic": "User experience"}, {"id": "w1-m21", "type": "mcq", "group": "w1", "prompt": "Which kind of rule has high authority and limited application?", "options": ["A standard", "A broad design principle", "An informal suggestion", "A designer’s preference"], "correct": 0, "explanation": "Standards are specific and authoritative within their scope.", "source": "Week 1 · PDF p. 77", "topic": "Rules"}, {"id": "w1-m22", "type": "mcq", "group": "w1", "prompt": "Why can a learned symbol be confusing across cultures?", "options": ["Its meaning may depend on conventions and prior experience", "Every symbol has a universal natural meaning", "Culture affects only font size", "All mappings are physical affordances"], "correct": 0, "explanation": "Cultural associations should not be assumed to be universal.", "source": "Week 1 · PDF p. 94", "topic": "Individual differences"}, {"id": "w1-m23", "type": "mcq", "group": "w1", "prompt": "An error message says only “Something went wrong.” What is the main weakness?", "options": ["It does not help users understand or recover from the failure", "It provides too many task-specific instructions", "It establishes a natural control mapping", "It prevents the failed action before it happens"], "correct": 0, "explanation": "Feedback should explain what happened in understandable terms.", "source": "Week 1 · PDF pp. 89–90", "topic": "Design principles"}, {"id": "w1-m24", "type": "mcq", "group": "w1", "prompt": "Which belongs to the UI beyond visual styling?", "options": ["Navigation, control behaviour and the conceptual model", "Only advertising copy", "Only database indexing", "Only the device’s processor"], "correct": 0, "explanation": "The UI includes all aspects that influence interaction.", "source": "Week 1 · PDF p. 69", "topic": "UI scope"}, {"id": "w1-m25", "type": "mcq", "group": "w1", "prompt": "Why might matching every app icon’s appearance hurt usability?", "options": ["Different functions can become hard to distinguish", "Consistency always requires identical icons", "Recognition works only with words", "Users cannot learn icon meanings"], "correct": 0, "explanation": "Consistency must preserve meaningful distinctions.", "source": "Week 1 · PDF p. 100", "topic": "Design principles"}, {"id": "w2-m01", "type": "mcq", "group": "w2", "prompt": "What is a mental model?", "options": ["A user’s internal understanding of how something works", "A complete technical specification", "A guaranteed accurate system diagram", "A fixed set of screen dimensions"], "correct": 0, "explanation": "Mental models help people predict system behaviour but may be wrong.", "source": "Week 2 · PDF pp. 8–11, 19", "topic": "Mental models"}, {"id": "w2-m02", "type": "mcq", "group": "w2", "prompt": "Through what does the designer mainly communicate the intended model?", "options": ["The system image: appearance, labels and behaviour", "Unseen implementation comments", "The CPU instruction set", "A persona’s fictional name alone"], "correct": 0, "explanation": "Users infer how a system works from what they encounter.", "source": "Week 2 · PDF pp. 15–17, 21", "topic": "Mental models"}, {"id": "w2-m03", "type": "mcq", "group": "w2", "prompt": "Which ordering matches Norman’s action cycle?", "options": ["Goal → intention → sequence → execute → perceive → interpret → evaluate", "Goal → execute → intention → evaluate → perceive → plan → interpret", "Perceive → evaluate → goal → interpret → act → plan → intend", "Intention → evaluate → act → goal → perceive → sequence → interpret"], "correct": 0, "explanation": "The cycle connects goal formation, execution, and evaluation.", "source": "Week 2 · PDF p. 13", "topic": "Action cycle"}, {"id": "w2-m04", "type": "mcq", "group": "w2", "prompt": "A user knows the goal but cannot discover the needed control. Which gulf is involved?", "options": ["Gulf of execution", "Gulf of evaluation", "A sensory-memory gulf", "A colour-space gulf"], "correct": 0, "explanation": "The execution gulf concerns translating intentions into available actions.", "source": "Week 2 · PDF p. 14", "topic": "Action cycle"}, {"id": "w2-m05", "type": "mcq", "group": "w2", "prompt": "A user clicks Submit but cannot tell whether it worked. Which gulf is involved?", "options": ["Gulf of evaluation", "Gulf of execution", "Positive transfer", "Near transfer"], "correct": 0, "explanation": "The evaluation gulf concerns understanding the system state and result.", "source": "Week 2 · PDF p. 14", "topic": "Action cycle"}, {"id": "w2-m06", "type": "mcq", "group": "w2", "prompt": "Noticing the words “Booking confirmed” is primarily which stage?", "options": ["Perceiving the state", "Forming the intention", "Evaluating against the goal", "Planning the action sequence"], "correct": 0, "explanation": "Perception is noticing the information; interpretation gives it meaning.", "source": "Week 2 · PDF p. 13", "topic": "Action cycle"}, {"id": "w2-m07", "type": "mcq", "group": "w2", "prompt": "Deciding that a confirmed appointment matches the requested time is which stage?", "options": ["Evaluating against the goal", "Executing the sequence", "Perceiving pixels", "Forming an initial intention"], "correct": 0, "explanation": "Evaluation compares the understood outcome with the goal.", "source": "Week 2 · PDF p. 13", "topic": "Action cycle"}, {"id": "w2-m08", "type": "mcq", "group": "w2", "prompt": "A visible checklist replaces remembering unfinished steps. What benefit does it provide?", "options": ["Externalizing information to reduce memory load", "Eliminating all cognitive processing", "Changing a binary input to analog", "Removing the need for a goal"], "correct": 0, "explanation": "External representations support cognition.", "source": "Week 2 · PDF pp. 26–28", "topic": "External cognition"}, {"id": "w2-m09", "type": "mcq", "group": "w2", "prompt": "Crossing completed items off a list is what?", "options": ["Annotation", "Cognitive tracing", "Negative transfer", "Controlled polling"], "correct": 0, "explanation": "Annotation modifies an existing representation by adding marks.", "source": "Week 2 · PDF p. 29", "topic": "External cognition"}, {"id": "w2-m10", "type": "mcq", "group": "w2", "prompt": "Rearranging letter tiles to explore words is what?", "options": ["Cognitive tracing", "A state transition alone", "Factual interviewing", "Photopic adaptation"], "correct": 0, "explanation": "Cognitive tracing manipulates external items into different arrangements.", "source": "Week 2 · PDF pp. 29–35", "topic": "External cognition"}, {"id": "w2-m11", "type": "mcq", "group": "w2", "prompt": "Why preserve a well-learned control mapping?", "options": ["Automatic processes are difficult to unlearn", "Automatic processes never cause errors", "Learning removes individual differences", "Controlled processes cannot adapt"], "correct": 0, "explanation": "Changing a habitual mapping can create errors and extra effort.", "source": "Week 2 · PDF pp. 43–45", "topic": "Cognition"}, {"id": "w2-m12", "type": "mcq", "group": "w2", "prompt": "Which task most clearly requires controlled processing?", "options": ["Working out an unfamiliar calculation", "Typing a familiar word as a skilled typist", "Executing a well-practised shortcut", "Performing a habitual motor sequence"], "correct": 0, "explanation": "Controlled processes require conscious attention.", "source": "Week 2 · PDF p. 44", "topic": "Cognition"}, {"id": "w2-m13", "type": "mcq", "group": "w2", "prompt": "Labels close to their fields use which Gestalt principle?", "options": ["Proximity", "Closure", "Continuity", "Opponent processing"], "correct": 0, "explanation": "Nearby items tend to be perceived as related.", "source": "Week 2 · PDF pp. 58–60", "topic": "Gestalt"}, {"id": "w2-m14", "type": "mcq", "group": "w2", "prompt": "Controls with the same shape and styling tend to form a group through what?", "options": ["Similarity", "Closure", "Homing", "Recall"], "correct": 0, "explanation": "Similarity groups objects through shared visual features.", "source": "Week 2 · PDF p. 61", "topic": "Gestalt"}, {"id": "w2-m15", "type": "mcq", "group": "w2", "prompt": "Recognizing an incomplete outline as a whole shape illustrates what?", "options": ["Closure", "Divided attention", "Negative transfer", "Dynamic range"], "correct": 0, "explanation": "Closure supports perceiving incomplete figures as wholes.", "source": "Week 2 · PDF p. 64", "topic": "Gestalt"}, {"id": "w2-m16", "type": "mcq", "group": "w2", "prompt": "Seeing a route as continuous despite an overlapping object illustrates what?", "options": ["Continuity", "Prestige bias", "Encoding failure", "Chunking by meaning"], "correct": 0, "explanation": "Continuity favours smooth, continuous objects or paths.", "source": "Week 2 · PDF pp. 62–63", "topic": "Gestalt"}, {"id": "w2-m17", "type": "mcq", "group": "w2", "prompt": "Why can a structured table be easier to scan than dense prose with the same information?", "options": ["Grouping and alignment support search", "The table must contain less information", "It increases working-memory capacity", "It removes the need for attention"], "correct": 0, "explanation": "Information organization affects search even at similar density.", "source": "Week 2 · PDF pp. 73–79, 124–126", "topic": "Visual hierarchy"}, {"id": "w2-m18", "type": "mcq", "group": "w2", "prompt": "Which photoreceptors support highly sensitive low-light vision?", "options": ["Rods", "Cones only", "The pupil", "The cornea"], "correct": 0, "explanation": "Rods support scotopic vision with low spatial detail.", "source": "Week 2 · PDF pp. 90, 97", "topic": "Vision"}, {"id": "w2-m19", "type": "mcq", "group": "w2", "prompt": "Why should error meaning also be communicated with text or symbols?", "options": ["Colour discrimination varies across users and conditions", "Colour never communicates anything useful", "Text eliminates all visual impairments", "Every display renders colour identically"], "correct": 0, "explanation": "Redundant cues reduce reliance on colour alone.", "source": "Week 2 · PDF pp. 110–114", "topic": "Colour"}, {"id": "w2-m20", "type": "mcq", "group": "w2", "prompt": "Which situation best illustrates inattentional blindness?", "options": ["Missing an unexpected object while concentrating elsewhere", "Forgetting a password after several months", "Being unable to hear a high-frequency sound", "Correctly recognizing a familiar icon"], "correct": 0, "explanation": "Focused attention can cause visible events to be missed.", "source": "Week 2 · PDF p. 127", "topic": "Attention"}, {"id": "w2-m21", "type": "mcq", "group": "w2", "prompt": "Failing to notice that a display changed while looking away is what?", "options": ["Change blindness", "Annotation", "Near transfer", "Deliberate practice"], "correct": 0, "explanation": "A change can go unnoticed even when the new state is visible.", "source": "Week 1 · PDF p. 46; Week 2 p. 127", "topic": "Attention"}, {"id": "w2-m22", "type": "mcq", "group": "w2", "prompt": "The Stroop effect illustrates what?", "options": ["Automatic reading interfering with controlled colour naming", "A joystick returning to centre", "The inability to recognize incomplete shapes", "A survey’s low response rate"], "correct": 0, "explanation": "Automatic processes can compete with a task needing conscious attention.", "source": "Week 2 · PDF p. 129", "topic": "Attention"}, {"id": "w2-m23", "type": "mcq", "group": "w2", "prompt": "Why are visible menu choices often easier than remembered commands?", "options": ["They support recognition rather than recall", "They increase long-term memory storage physically", "They remove every choice from the task", "They depend only on auditory memory"], "correct": 0, "explanation": "Recognizing presented information generally places less demand on memory.", "source": "Week 2 · PDF pp. 139, 145–146", "topic": "Memory"}, {"id": "w2-m24", "type": "mcq", "group": "w2", "prompt": "Grouping a phone number into familiar units primarily supports what?", "options": ["Chunking", "Colour opponency", "A physical neutral position", "Far transfer by default"], "correct": 0, "explanation": "Meaningful groups reduce the number of separate units to process.", "source": "Week 2 · PDF pp. 142–144", "topic": "Memory"}, {"id": "w2-m25", "type": "mcq", "group": "w2", "prompt": "Why can tiny fonts and jargon reduce comprehension?", "options": ["They can force more effortful reading and burden working memory", "They reliably speed up automatic reading", "They improve recognition through unfamiliarity", "They prevent users from needing context"], "correct": 0, "explanation": "Poor text presentation increases reading effort.", "source": "Week 2 · PDF pp. 149–160", "topic": "Reading"}, {"id": "w3-m01", "type": "mcq", "group": "w3", "prompt": "An input reports how far it moved since the last reading. How is it classified?", "options": ["Relative", "Absolute", "Binary by definition", "Direct by definition"], "correct": 0, "explanation": "Relative input reports a change rather than an absolute position.", "source": "Week 3 · PDF p. 4", "topic": "Device taxonomy"}, {"id": "w3-m02", "type": "mcq", "group": "w3", "prompt": "A touchscreen reports the touched location. Which classification is most appropriate?", "options": ["Absolute and direct", "Relative and indirect", "Binary and indirect", "Relative and binary"], "correct": 0, "explanation": "A touchscreen normally supplies coordinates on the display itself.", "source": "Week 3 · PDF pp. 4–5", "topic": "Device taxonomy"}, {"id": "w3-m03", "type": "mcq", "group": "w3", "prompt": "Moving a mouse on a desk to move a screen pointer is what kind of input?", "options": ["Indirect", "Direct", "Always one-dimensional", "Always absolute"], "correct": 0, "explanation": "An indirect device maps action elsewhere onto screen activity.", "source": "Week 3 · PDF p. 5", "topic": "Device taxonomy"}, {"id": "w3-m04", "type": "mcq", "group": "w3", "prompt": "What distinguishes analog from binary input in this lecture?", "options": ["A range of values rather than two states", "A device using electricity rather than springs", "An input that must use an analog cable", "A device that always returns to centre"], "correct": 0, "explanation": "Analog here describes values, even when digitally encoded.", "source": "Week 3 · PDF p. 6", "topic": "Device taxonomy"}, {"id": "w3-m05", "type": "mcq", "group": "w3", "prompt": "Which control normally has a spring-return neutral position?", "options": ["A joystick", "A mouse body", "A touchscreen’s stored coordinates", "A trackball’s physical location"], "correct": 0, "explanation": "Joysticks commonly return to the centre when released.", "source": "Week 3 · PDF pp. 7, 15", "topic": "Device taxonomy"}, {"id": "w3-m06", "type": "mcq", "group": "w3", "prompt": "What does the dimensionality of a device describe?", "options": ["The independent values it transmits", "Its physical screen diagonal", "The number of installed apps", "Its battery capacity"], "correct": 0, "explanation": "A 2D position input provides two components such as X and Y.", "source": "Week 3 · PDF p. 3", "topic": "Device taxonomy"}, {"id": "w3-m07", "type": "mcq", "group": "w3", "prompt": "Which is a typical one-dimensional relative input?", "options": ["An unlimited-turn mouse wheel", "A touchscreen’s X and Y position", "A GPS position including altitude", "A six-degree-of-freedom tracker"], "correct": 0, "explanation": "The wheel reports movement along one input dimension.", "source": "Week 3 · PDF p. 10", "topic": "Devices"}, {"id": "w3-m08", "type": "mcq", "group": "w3", "prompt": "What is mouse clutching?", "options": ["Repositioning the mouse to continue pointer travel", "Holding a key to repeat text", "Tilting a joystick to set speed", "Locking a touchscreen orientation"], "correct": 0, "explanation": "Clutching overcomes limits of physical travel on the surface.", "source": "Week 3 · PDF p. 11", "topic": "Devices"}, {"id": "w3-m09", "type": "mcq", "group": "w3", "prompt": "Why may a mouse be poor for a steering task requiring a resting centre?", "options": ["It lacks an automatic neutral return", "It cannot report X and Y", "It only has binary movement", "It cannot support precise pointing"], "correct": 0, "explanation": "No automatic centre can make steering state harder to manage.", "source": "Week 3 · PDF p. 12", "topic": "Devices"}, {"id": "w3-m10", "type": "mcq", "group": "w3", "prompt": "Why are small touch targets difficult?", "options": ["Finger imprecision and occlusion", "Touch input cannot report coordinates", "High pixel resolution guarantees large controls", "All users have the same finger size"], "correct": 0, "explanation": "A finger can cover and inaccurately select a small target.", "source": "Week 3 · PDF pp. 13, 48, 52", "topic": "Mobile input"}, {"id": "w3-m11", "type": "mcq", "group": "w3", "prompt": "A touchpad senses finger coordinates but moves a cursor by changes in those coordinates. What is true?", "options": ["Absolute sensing can support relative pointer behaviour", "Its hardware must be binary", "Its cursor is necessarily direct input", "The two descriptions are impossible together"], "correct": 0, "explanation": "Sensor readings and software interpretation are different levels.", "source": "Week 3 · PDF pp. 4, 13", "topic": "Device taxonomy"}, {"id": "w3-m12", "type": "mcq", "group": "w3", "prompt": "Why is a joystick useful for continuous steering?", "options": ["Tilt can represent direction and movement rate", "It has unlimited physical travel", "It always outperforms a mouse for precise pointing", "It reports geographic coordinates"], "correct": 0, "explanation": "Limited tilt can control ongoing movement by rate.", "source": "Week 3 · PDF pp. 15–16", "topic": "Devices"}, {"id": "w3-m13", "type": "mcq", "group": "w3", "prompt": "How can a D-pad provide diagonal directions?", "options": ["By activating two directional switches together", "By measuring latitude and longitude", "By continuously estimating rotation", "By physically rotating the entire display"], "correct": 0, "explanation": "Combinations of the four switches support eight directions.", "source": "Week 3 · PDF p. 17", "topic": "Devices"}, {"id": "w3-m14", "type": "mcq", "group": "w3", "prompt": "What does an accelerometer measure?", "options": ["Acceleration", "Angular velocity", "Magnetic field only", "Latitude and longitude"], "correct": 0, "explanation": "The accelerometer measures acceleration, including gravity-related readings.", "source": "Week 3 · PDF p. 18", "topic": "Sensors"}, {"id": "w3-m15", "type": "mcq", "group": "w3", "prompt": "What does a gyroscope measure?", "options": ["Angular velocity", "Linear position", "Ambient illumination", "Food energy"], "correct": 0, "explanation": "Angular velocity is the rate of rotation.", "source": "Week 3 · PDF p. 19", "topic": "Sensors"}, {"id": "w3-m16", "type": "mcq", "group": "w3", "prompt": "What can be estimated by integrating angular velocity?", "options": ["Orientation change", "Sound pressure", "Screen luminance", "A food’s nutrient composition"], "correct": 0, "explanation": "Integrating rotation rate estimates a change in orientation.", "source": "Week 3 · PDF p. 19", "topic": "Sensors"}, {"id": "w3-m17", "type": "mcq", "group": "w3", "prompt": "Why does estimating position from acceleration become inaccurate?", "options": ["Noise accumulates through integration", "Acceleration is identical to absolute position", "Integration removes every measurement error", "A gyroscope supplies error-free geographic coordinates"], "correct": 0, "explanation": "Double integration can accumulate error and drift.", "source": "Week 3 · PDF p. 18", "topic": "Sensors"}, {"id": "w3-m18", "type": "mcq", "group": "w3", "prompt": "Which sensor supports geographic location-based results?", "options": ["GPS", "A proximity sensor", "A gyroscope alone", "A light sensor"], "correct": 0, "explanation": "GPS provides geographic position.", "source": "Week 3 · PDF p. 20", "topic": "Sensors"}, {"id": "w3-m19", "type": "mcq", "group": "w3", "prompt": "Which sensor can contribute to compass heading?", "options": ["Magnetometer", "Microphone only", "Proximity sensor only", "Screen touch pressure only"], "correct": 0, "explanation": "A magnetometer measures magnetic-field components.", "source": "Week 3 · PDF p. 21", "topic": "Sensors"}, {"id": "w3-m20", "type": "mcq", "group": "w3", "prompt": "What is a derived sensor reading?", "options": ["Information calculated by combining or processing sensor data", "A sensor with no measured input", "An exclusively mechanical switch", "A guarantee of perfect position"], "correct": 0, "explanation": "Orientation and linear acceleration can be derived from sensor readings.", "source": "Week 3 · PDF p. 23", "topic": "Sensors"}, {"id": "w3-m21", "type": "mcq", "group": "w3", "prompt": "Six degrees of freedom includes what?", "options": ["Three translations and three rotations", "Six independent colour channels", "Six geographic latitudes", "Six binary keyboard keys"], "correct": 0, "explanation": "3D tracking can represent position and orientation.", "source": "Week 3 · PDF p. 24", "topic": "Tracking"}, {"id": "w3-m22", "type": "mcq", "group": "w3", "prompt": "What distinguishes haptic feedback?", "options": ["It provides tactile or force information", "It exclusively changes font size", "It always uses spoken instructions", "It is geographic positioning"], "correct": 0, "explanation": "Haptic devices create physical feedback.", "source": "Week 3 · PDF p. 25", "topic": "Tracking"}, {"id": "w3-m23", "type": "mcq", "group": "w3", "prompt": "Why should a VR interface reconsider corner-based status displays?", "options": ["They can be uncomfortable to monitor and cause eye strain", "VR makes all text automatically larger", "A desktop layout is always optimal in VR", "Head movement eliminates attention limits"], "correct": 0, "explanation": "VR changes viewing, navigation, safety, and feedback requirements.", "source": "Week 3 · PDF pp. 30–35", "topic": "VR"}, {"id": "w3-m24", "type": "mcq", "group": "w3", "prompt": "Why use events rather than repeatedly polling on mobile?", "options": ["To reduce unnecessary activity and wake-ups", "To guarantee network connectivity", "To remove the need for a processor", "To disable all notifications"], "correct": 0, "explanation": "Event-driven updates can help conserve limited energy.", "source": "Week 3 · PDF pp. 46–47", "topic": "Mobile constraints"}, {"id": "w3-m25", "type": "mcq", "group": "w3", "prompt": "What makes mobile design more than shrinking a desktop layout?", "options": ["Touch, context, attention, resources and usage patterns differ", "Only the number of pixels differs", "Mobile users never multitask", "Responsive layout guarantees every task is easy"], "correct": 0, "explanation": "Mobile design must support the actual platform and use context.", "source": "Week 3 · PDF pp. 41–65", "topic": "Mobile constraints"}, {"id": "w4-m01", "type": "mcq", "group": "w4", "prompt": "What is the starting question of task-centred design?", "options": ["Who will use the system to do exactly what?", "Which framework has the most features?", "Which colour is fashionable?", "How can users be trained to accept the design?"], "correct": 0, "explanation": "Task-centred design begins with users and concrete tasks.", "source": "Week 4 · PDF p. 6", "topic": "Requirements"}, {"id": "w4-m02", "type": "mcq", "group": "w4", "prompt": "Which is a functional requirement?", "options": ["Allow users to cancel a booking", "Respond within one second", "Keep information no more than five minutes old", "Remain readable in the intended lighting"], "correct": 0, "explanation": "A functional requirement describes what the system does.", "source": "Week 4 · PDF p. 17", "topic": "Requirements"}, {"id": "w4-m03", "type": "mcq", "group": "w4", "prompt": "Which is a non-functional requirement?", "options": ["Search results appear within the selected time target", "Users can search for meals", "Users can delete entries", "Users can create a shopping list"], "correct": 0, "explanation": "A non-functional requirement sets a quality or constraint.", "source": "Week 4 · PDF p. 17", "topic": "Requirements"}, {"id": "w4-m04", "type": "mcq", "group": "w4", "prompt": "Which statement about users is most accurate?", "options": ["A frequent user can remain inexperienced in many features", "Every frequent user becomes an expert", "Every expert uses the system daily", "Occasional users never need guidance"], "correct": 0, "explanation": "Expertise and frequency of use are distinct.", "source": "Week 4 · PDF pp. 16, 27–28", "topic": "Users"}, {"id": "w4-m05", "type": "mcq", "group": "w4", "prompt": "A person affected by a system but not operating it is what?", "options": ["A stakeholder", "Necessarily its primary user", "Necessarily the interface designer", "Not relevant to requirements"], "correct": 0, "explanation": "Stakeholders influence or are affected by the system.", "source": "Week 4 · PDF p. 21", "topic": "Users"}, {"id": "w4-m06", "type": "mcq", "group": "w4", "prompt": "Noise, vibration and lighting belong to which context?", "options": ["Physical", "Organizational hierarchy", "A use-case postcondition", "A persona name"], "correct": 0, "explanation": "Physical context affects how interaction works.", "source": "Week 4 · PDF p. 18", "topic": "Context"}, {"id": "w4-m07", "type": "mcq", "group": "w4", "prompt": "Why ask why a user requests a feature?", "options": ["To identify the underlying goal", "To prove users never know their needs", "To reject every request", "To choose colours before understanding tasks"], "correct": 0, "explanation": "A requested feature may be one possible means to a goal.", "source": "Week 4 · PDF pp. 23–26", "topic": "Requirements"}, {"id": "w4-m08", "type": "mcq", "group": "w4", "prompt": "Which interview combines prepared questions with flexible follow-up?", "options": ["Semi-structured", "Structured only", "A closed survey only", "A state-machine interview"], "correct": 0, "explanation": "Semi-structured interviewing covers a guide while exploring new issues.", "source": "Week 4 · PDF p. 31", "topic": "Interviews"}, {"id": "w4-m09", "type": "mcq", "group": "w4", "prompt": "What is a limitation of interviews?", "options": ["Reported accounts can be subjective and affected by the interviewer", "They can never explore reasons", "They require no analysis", "They directly capture all real behaviour"], "correct": 0, "explanation": "Interviews provide reported information and can introduce bias.", "source": "Week 4 · PDF pp. 30–33", "topic": "Interviews"}, {"id": "w4-m10", "type": "mcq", "group": "w4", "prompt": "Which question is least leading?", "options": ["Tell me how you completed your last booking.", "Wasn’t our booking screen convenient?", "You liked the easy controls, right?", "Would you agree our excellent design saved time?"], "correct": 0, "explanation": "A concrete neutral question avoids suggesting a desired answer.", "source": "Week 4 · PDF pp. 33, 42", "topic": "Bias"}, {"id": "w4-m11", "type": "mcq", "group": "w4", "prompt": "What can distort a focus group’s apparent agreement?", "options": ["Dominant participants and reluctance to disagree", "Its use of a moderator by itself", "Every person being asked the same task", "Participants seeing the same mock-up"], "correct": 0, "explanation": "Social dynamics can suppress individual opinions.", "source": "Week 4 · PDF pp. 35–36", "topic": "Focus groups"}, {"id": "w4-m12", "type": "mcq", "group": "w4", "prompt": "Which question is primarily attitudinal?", "options": ["How useful was the task summary?", "How many appointments did you book yesterday?", "Which browser version did you use?", "How long have you used the system?"], "correct": 0, "explanation": "Attitudinal questions examine judgments and preferences.", "source": "Week 4 · PDF p. 39", "topic": "Questionnaires"}, {"id": "w4-m13", "type": "mcq", "group": "w4", "prompt": "How does ranking differ from rating?", "options": ["Ranking orders items; rating judges items on a scale", "Ranking always explains reasons", "Rating forces every item into a unique order", "The two methods are identical"], "correct": 0, "explanation": "Rank order does not directly show the strength of each judgment.", "source": "Week 4 · PDF p. 41", "topic": "Questionnaires"}, {"id": "w4-m14", "type": "mcq", "group": "w4", "prompt": "A respondent exaggerates expertise to look impressive. Which bias is illustrated?", "options": ["Prestige bias", "Change blindness", "Control-display mapping", "A relative input effect"], "correct": 0, "explanation": "Prestige bias changes answers to improve perceived status.", "source": "Week 4 · PDF p. 42", "topic": "Bias"}, {"id": "w4-m15", "type": "mcq", "group": "w4", "prompt": "What is funnelling in question design?", "options": ["Moving from broad questions to specific ones", "Starting by praising the feature", "Repeating the same question until agreement", "Combining unrelated topics in one question"], "correct": 0, "explanation": "Funnelling establishes context without prematurely directing answers.", "source": "Week 4 · PDF p. 43", "topic": "Questionnaires"}, {"id": "w4-m16", "type": "mcq", "group": "w4", "prompt": "What is simple observation’s main limitation?", "options": ["It may not reveal users’ reasoning", "It cannot reveal actions", "It always provides a full mental model", "It removes observer influence"], "correct": 0, "explanation": "Watching reveals behaviour, but may not explain why.", "source": "Week 4 · PDF p. 48", "topic": "Observation"}, {"id": "w4-m17", "type": "mcq", "group": "w4", "prompt": "What does think-aloud add to observation?", "options": ["Users verbalize goals, beliefs and reasons", "Users silently rank colours", "An evaluator performs every task", "A model automatically assigns grades"], "correct": 0, "explanation": "Think-aloud offers reasoning but can also alter performance.", "source": "Week 4 · PDF p. 49", "topic": "Observation"}, {"id": "w4-m18", "type": "mcq", "group": "w4", "prompt": "Which best describes co-discovery in the lecture?", "options": ["A novice uses the interface while conversing with a coach", "An evaluator secretly changes responses", "A group silently completes a questionnaire", "An expert demonstrates while the novice watches silently"], "correct": 0, "explanation": "Conversation can reveal reasoning more naturally than continuous narration.", "source": "Week 4 · PDF p. 50", "topic": "Observation"}, {"id": "w4-m19", "type": "mcq", "group": "w4", "prompt": "Context, partnership, interpretation and focus are principles of what?", "options": ["Contextual inquiry", "A Likert scale", "HTA decomposition", "Colour naming"], "correct": 0, "explanation": "Contextual inquiry studies actual activity through focused collaboration.", "source": "Week 4 · PDF pp. 55–56", "topic": "Contextual inquiry"}, {"id": "w4-m20", "type": "mcq", "group": "w4", "prompt": "What does triangulation involve?", "options": ["Combining techniques or sources to examine a question", "Using exactly three participants in every study", "Repeating one leading question", "Treating one survey as complete proof"], "correct": 0, "explanation": "Multiple perspectives can corroborate or challenge findings.", "source": "Week 4 · PDF p. 61", "topic": "Research design"}, {"id": "w4-m21", "type": "mcq", "group": "w4", "prompt": "What makes a persona appropriate for requirements work?", "options": ["It synthesizes meaningful characteristics from real user data", "It matches the designer’s ideal user", "It uses a realistic photo without evidence", "It replaces all user research"], "correct": 0, "explanation": "Personas should represent evidence rather than convenient inventions.", "source": "Week 4 · PDF p. 66", "topic": "Personas"}, {"id": "w4-m22", "type": "mcq", "group": "w4", "prompt": "Which description matches a scenario in this lecture?", "options": ["A concrete narrative following one path in context", "A branching specification of every possible screen", "A database schema", "A list of colour values"], "correct": 0, "explanation": "Scenarios tell a particular story without conditional branches.", "source": "Week 4 · PDF pp. 68–69", "topic": "Models"}, {"id": "w4-m23", "type": "mcq", "group": "w4", "prompt": "What do essential use cases emphasize?", "options": ["User intentions and system responsibilities", "Exact icon locations and click coordinates", "Only exception codes", "Hardware benchmark results"], "correct": 0, "explanation": "They abstract away from specific interface details.", "source": "Week 4 · PDF p. 75", "topic": "Models"}, {"id": "w4-m24", "type": "mcq", "group": "w4", "prompt": "What does an HTA plan specify?", "options": ["Order, conditions and repetition of subtasks", "Only font choices", "Only a fictional user’s age", "Only the database transaction count"], "correct": 0, "explanation": "A hierarchy needs a plan to describe how tasks are performed.", "source": "Week 4 · PDF pp. 77–79", "topic": "HTA"}, {"id": "w4-m25", "type": "mcq", "group": "w4", "prompt": "What does a state diagram primarily represent?", "options": ["System states and transitions", "The target users’ biographies", "A list of functional goals alone", "The ranking of survey responses"], "correct": 0, "explanation": "State diagrams expose conditions and transitions such as loading and errors.", "source": "Week 4 · PDF p. 82", "topic": "State diagrams"}, {"id": "project-m01", "type": "mcq", "group": "project", "prompt": "For a four-member group, how many complex tasks should the interface support under the topic rule?", "options": ["At least four", "Exactly one", "Two regardless of membership", "Only as many as fit one screen"], "correct": 0, "explanation": "The supplied topic rule ties complex-task count to group size.", "source": "Project topic brief", "topic": "Assignment scope"}, {"id": "project-m02", "type": "mcq", "group": "project", "prompt": "How many people should submit the group declaration?", "options": ["One member for the whole group", "Every member separately", "Only the instructor", "No one if a topic was discussed"], "correct": 0, "explanation": "The supplied instructions require one group submission.", "source": "Group declaration brief", "topic": "Declaration"}, {"id": "project-m03", "type": "mcq", "group": "project", "prompt": "What must each member line in the declaration contain?", "options": ["Official name, email, repeated group/topic name", "Nickname and favourite app", "Only the team name", "Only the topic description"], "correct": 0, "explanation": "The required format is comma-separated name, email and group name.", "source": "Group declaration brief", "topic": "Declaration"}, {"id": "project-m04", "type": "mcq", "group": "project", "prompt": "What is the stated questionnaire maximum?", "options": ["Seven closed-ended and two open-ended questions", "Ten open-ended questions", "Seven questions of any kind without restrictions", "Two closed-ended and seven open-ended questions"], "correct": 0, "explanation": "Use Google Forms and include its link in the submission.", "source": "Walkthrough brief · Questionnaire", "topic": "Questionnaire"}, {"id": "project-m05", "type": "mcq", "group": "project", "prompt": "Which walkthrough component has the greatest marking weight?", "options": ["Conceptual model and low-fidelity prototype", "Problem overview", "Requirements and tasks", "Questionnaire alone"], "correct": 0, "explanation": "The supplied weights are 40%, 15%, 20%, and 25% respectively.", "source": "Walkthrough brief · Marking scheme", "topic": "Assignment scope"}, {"id": "project-m06", "type": "mcq", "group": "project", "prompt": "Which statement is an appropriately testable design rationale?", "options": ["We expect fewer steps to help; we will test task completion.", "The design is obviously perfect.", "AI makes usability evaluation unnecessary.", "Everyone will find the interface intuitive."], "correct": 0, "explanation": "The brief asks for observable evidence and explicit hypotheses.", "source": "Walkthrough brief · Prototype", "topic": "Design evidence"}, {"id": "project-m07", "type": "mcq", "group": "project", "prompt": "For the nutrition concept, what does a daily food log establish by itself?", "options": ["Logged estimated intake, not actual energy balance", "A guaranteed physiological calorie deficit", "Clinically optimal sleep timing", "The user’s exact energy expenditure"], "correct": 0, "explanation": "Your idea needs clear distinctions between logs, targets and untested claims.", "source": "Idea screenshot + proposed project outline", "topic": "Nutrition concept"}, {"id": "project-m08", "type": "mcq", "group": "project", "prompt": "Which flow is more substantial for the prototype?", "options": ["Choose a meal, inspect a suggestion, swap an ingredient, then save a shopping list", "Show one static food icon", "Open a decorative splash screen", "Rename the app"], "correct": 0, "explanation": "A complex task connects decisions, screens, results and recovery.", "source": "Idea screenshot + project task rule", "topic": "Nutrition concept"}, {"id": "extra-m01", "type": "mcq", "group": "extra", "prompt": "In the other professor’s photo, which HTML input type selects a date?", "options": ["input type=\"date\"", "input type=\"calendar\"", "input type=\"schedule\"", "input type=\"appointment\""], "correct": 0, "explanation": "The photo’s date-input question uses the standard date type.", "source": "Other professor · IMG_4847.JPG", "topic": "HTML / CSS"}, {"id": "extra-m02", "type": "mcq", "group": "extra", "prompt": "In the supplied sample, what does .col-md-6 represent?", "options": ["Half-width at medium screens and up", "Six rows on medium screens", "A fixed 600-pixel width", "A non-responsive column"], "correct": 0, "explanation": "Six of twelve grid columns occupy half the row at the applicable breakpoint.", "source": "Other professor · IMG_4847.JPG", "topic": "HTML / CSS"}, {"id": "extra-m03", "type": "mcq", "group": "extra", "prompt": "Which selector targets paragraph descendants of a div?", "options": ["div p", "div.p", "p div", "div > p2"], "correct": 0, "explanation": "The space is the descendant combinator.", "source": "Other professor · IMG_4847.JPG", "topic": "HTML / CSS"}, {"id": "extra-m04", "type": "mcq", "group": "extra", "prompt": "Which sample item is quantitative usability data?", "options": ["Task-completion time", "A frustration comment", "An open interview response", "A suggestion in the user’s words"], "correct": 0, "explanation": "Time is a numerical measure; comments provide qualitative information.", "source": "Other professor · IMG_4847.JPG", "topic": "Evaluation extras"}, {"id": "extra-m05", "type": "mcq", "group": "extra", "prompt": "Which chart is best for comparing categories in the sample?", "options": ["Bar chart", "Line chart for a time trend", "Scatterplot for two-variable relationships", "Box plot for distribution summaries"], "correct": 0, "explanation": "Bars support comparison across categories.", "source": "Other professor · IMG_4848.JPG", "topic": "Evaluation extras"}, {"id": "extra-m06", "type": "mcq", "group": "extra", "prompt": "A single 1–5 Likert item is classified as what in the supplied sample?", "options": ["Ordinal", "Ratio", "Nominal", "Automatically interval"], "correct": 0, "explanation": "The response categories are ordered; equal gaps are not guaranteed.", "source": "Other professor · IMG_4848.JPG", "topic": "Evaluation extras"}, {"id": "extra-m07", "type": "mcq", "group": "extra", "prompt": "Which method in the sample is qualitative analysis?", "options": ["Thematic analysis", "Task-completion time", "Error rate", "Completion percentage"], "correct": 0, "explanation": "Thematic analysis identifies patterns in qualitative data.", "source": "Other professor · IMG_4848.JPG", "topic": "Evaluation extras"}, {"id": "extra-m08", "type": "mcq", "group": "extra", "prompt": "Which best matches user control and freedom in the sample?", "options": ["Allow users to leave and reverse actions where appropriate", "Prohibit undo", "Make every button identical", "Prevent all choices"], "correct": 0, "explanation": "The supplied question emphasizes exits and reversible actions.", "source": "Other professor · IMG_4847.JPG", "topic": "Evaluation extras"}, {"id": "context-m01", "type": "mcq", "group": "context", "prompt": "What is the central idea of constructivist perception in the excluded slides?", "options": ["Perception uses sensory information and prior knowledge", "Vision is an exact camera copy", "Prior experience never affects seeing", "Perception depends only on keyboard input"], "correct": 0, "explanation": "These Week 2 slides are explicitly marked Not on test.", "source": "Week 2 · PDF pp. 66–70 · Not on test", "topic": "Constructivism"}, {"id": "context-m02", "type": "mcq", "group": "context", "prompt": "Gregory’s hypothesis theory treats perception as what?", "options": ["Building interpretations of the world from received stimuli", "Measuring only processor speed", "Ignoring familiar objects", "An error-free reproduction of light"], "correct": 0, "explanation": "This theory is background material in slides marked Not on test.", "source": "Week 2 · PDF p. 69 · Not on test", "topic": "Constructivism"}, {"id": "context-m03", "type": "mcq", "group": "context", "prompt": "Interaural level differences refer to what?", "options": ["Differences in sound level at the two ears", "Differences in colour between two eyes", "Only the text size on a screen", "The number of sensory stores"], "correct": 0, "explanation": "The detailed sound-localization slide is marked Not on test.", "source": "Week 2 · PDF p. 86 · Not on test", "topic": "Sound localization"}, {"id": "context-m04", "type": "mcq", "group": "context", "prompt": "Interaural time differences involve what?", "options": ["Differences in when sound reaches each ear", "Changes in screen refresh rate", "The time taken to read a command", "The time between keyboard events"], "correct": 0, "explanation": "This is optional background from the sound-localization slide.", "source": "Week 2 · PDF p. 86 · Not on test", "topic": "Sound localization"}, {"id": "w1-s01", "type": "short", "group": "w1", "prompt": "Distinguish utility from usability.", "answer": ["Utility means the system provides the functions users need.", "Usability means users can operate those functions successfully and easily."], "source": "Week 1 · PDF pp. 73, 78", "topic": "Usability goals"}, {"id": "w1-s02", "type": "short", "group": "w1", "prompt": "Distinguish effectiveness from efficiency.", "answer": ["Effectiveness is completing the intended goal accurately.", "Efficiency is the time and effort required to complete it."], "source": "Week 1 · PDF p. 73", "topic": "Usability goals"}, {"id": "w1-s03", "type": "short", "group": "w1", "prompt": "Distinguish learnability from memorability.", "answer": ["Learnability concerns learning to use a system initially.", "Memorability concerns remembering how to use it after time away."], "source": "Week 1 · PDF p. 73", "topic": "Usability goals"}, {"id": "w1-s04", "type": "short", "group": "w1", "prompt": "Explain why design should account for human error.", "answer": ["Distraction, fatigue and memory limits are predictable human characteristics.", "Design should reduce likely errors and support recovery instead of simply blaming users."], "source": "Week 1 · PDF pp. 42–43, 59", "topic": "Human error"}, {"id": "w1-s05", "type": "short", "group": "w1", "prompt": "Define mapping and give one example.", "answer": ["Mapping is the relationship between controls and their effects.", "Stove controls matching burner positions make the relationship easier to understand."], "source": "Week 1 · PDF p. 87", "topic": "Design principles"}, {"id": "w1-s06", "type": "short", "group": "w1", "prompt": "Distinguish visibility from feedback.", "answer": ["Visibility makes available actions or relevant states apparent.", "Feedback communicates what happened after an action."], "source": "Week 1 · PDF pp. 88–91", "topic": "Design principles"}, {"id": "w1-s07", "type": "short", "group": "w1", "prompt": "Define a perceived affordance in a graphical interface.", "answer": ["Appearance and learned conventions suggest how an interface element can be used.", "A button’s familiar styling suggests that it can be clicked."], "source": "Week 1 · PDF pp. 80–81", "topic": "Design principles"}, {"id": "w1-s08", "type": "short", "group": "w1", "prompt": "A disabled time selector gives no reason. Identify a problem and a fix.", "answer": ["The constraint is unexplained, so users cannot determine what to do next.", "Show “Choose a doctor and date first” beside the selector."], "source": "Week 1 · PDF pp. 91, 96", "topic": "Application"}, {"id": "w1-s09", "type": "short", "group": "w1", "prompt": "Explain positive and negative transfer.", "answer": ["Positive transfer occurs when prior experience helps a new task.", "Negative transfer occurs when prior experience interferes with it."], "source": "Week 1 · PDF pp. 50–51, 92–93", "topic": "Transfer"}, {"id": "w1-s10", "type": "short", "group": "w1", "prompt": "Why does consistency matter?", "answer": ["Stable controls and terminology reduce learning demands and support familiar habits.", "Similar operations should behave similarly while different functions remain distinguishable."], "source": "Week 1 · PDF pp. 97–100", "topic": "Design principles"}, {"id": "w1-s11", "type": "short", "group": "w1", "prompt": "Distinguish usability goals from UX goals.", "answer": ["Usability goals concern successful, efficient, safe and learnable interaction.", "UX goals concern experiences such as satisfaction, engagement and enjoyment."], "source": "Week 1 · PDF pp. 73, 76", "topic": "User experience"}, {"id": "w1-s12", "type": "short", "group": "w1", "prompt": "What makes interface design iterative and user-centred?", "answer": ["Designers involve users and evaluate ideas throughout development.", "Findings guide repeated changes to requirements, prototypes and interaction design."], "source": "Week 1 · PDF pp. 5–6, 63", "topic": "Design process"}, {"id": "w2-s01", "type": "short", "group": "w2", "prompt": "List Norman’s seven stages in order.", "answer": ["Establish goal → form intention → decide sequence → execute sequence.", "Perceive state → interpret state → evaluate against the goal."], "source": "Week 2 · PDF p. 13", "topic": "Action cycle"}, {"id": "w2-s02", "type": "short", "group": "w2", "prompt": "Distinguish the gulf of execution from the gulf of evaluation.", "answer": ["Execution is the gap between an intention and understanding how to act.", "Evaluation is the gap between the system state and understanding what happened."], "source": "Week 2 · PDF p. 14", "topic": "Action cycle"}, {"id": "w2-s03", "type": "short", "group": "w2", "prompt": "A booking produces no confirmation. Identify the gulf and one improvement.", "answer": ["The gulf of evaluation increases because the user cannot understand the result.", "Show a noticeable confirmation with the booked details, or a specific error."], "source": "Week 2 · PDF pp. 13–14", "topic": "Application"}, {"id": "w2-s04", "type": "short", "group": "w2", "prompt": "What is a mental model, and how can it be wrong?", "answer": ["A mental model is a user’s internal understanding of how a system works.", "It can be incomplete or mistaken, leading to inaccurate predictions."], "source": "Week 2 · PDF pp. 8–11, 19", "topic": "Mental models"}, {"id": "w2-s05", "type": "short", "group": "w2", "prompt": "How does the system image communicate the intended model?", "answer": ["Users infer behaviour from the interface’s appearance, labels, instructions and responses.", "An unclear system image can produce a model that differs from the designer’s intention."], "source": "Week 2 · PDF pp. 15–17, 21", "topic": "Mental models"}, {"id": "w2-s06", "type": "short", "group": "w2", "prompt": "Distinguish annotation from cognitive tracing.", "answer": ["Annotation adds marks to an existing representation, such as crossing off a task.", "Cognitive tracing rearranges external items, such as moving letter tiles."], "source": "Week 2 · PDF p. 29", "topic": "External cognition"}, {"id": "w2-s07", "type": "short", "group": "w2", "prompt": "Explain why recognition is often easier than recall.", "answer": ["Recognition identifies information when it is presented; recall retrieves it without that cue.", "Visible menus and examples reduce demands on users’ memory."], "source": "Week 2 · PDF pp. 139, 145–146", "topic": "Memory"}, {"id": "w2-s08", "type": "short", "group": "w2", "prompt": "Explain chunking and give an interface example.", "answer": ["Chunking groups information into meaningful units rather than separate items.", "Displaying a phone number in grouped digits makes it easier to process."], "source": "Week 2 · PDF pp. 142–146", "topic": "Memory"}, {"id": "w2-s09", "type": "short", "group": "w2", "prompt": "Distinguish proximity from similarity.", "answer": ["Proximity groups elements by how close together they appear.", "Similarity groups elements by shared appearance, such as shape or styling."], "source": "Week 2 · PDF pp. 58–61", "topic": "Gestalt"}, {"id": "w2-s10", "type": "short", "group": "w2", "prompt": "Distinguish inattentional blindness from change blindness.", "answer": ["Inattentional blindness means missing something while attention is occupied elsewhere.", "Change blindness means failing to notice a change in the environment or display."], "source": "Week 1 · PDF p. 46; Week 2 p. 127", "topic": "Attention"}, {"id": "w2-s11", "type": "short", "group": "w2", "prompt": "Why should an error use more than colour?", "answer": ["Colour discrimination varies across users, object sizes and viewing conditions.", "Add a clear message or symbol so meaning does not depend on colour alone."], "source": "Week 2 · PDF pp. 110–114", "topic": "Colour"}, {"id": "w2-s12", "type": "short", "group": "w2", "prompt": "Why do jargon and poor text presentation make interaction harder?", "answer": ["They can force effortful interpretation and burden working memory.", "Use readable text and concise, familiar wording that supports the task."], "source": "Week 2 · PDF pp. 149–160", "topic": "Reading"}, {"id": "w3-s01", "type": "short", "group": "w3", "prompt": "Distinguish absolute from relative input.", "answer": ["Absolute input reports a position or value in a reference range.", "Relative input reports change from a previous position, as with mouse movement."], "source": "Week 3 · PDF p. 4", "topic": "Device taxonomy"}, {"id": "w3-s02", "type": "short", "group": "w3", "prompt": "Distinguish direct from indirect input.", "answer": ["Direct input acts on the target, as when touching an on-screen control.", "Indirect input maps an action elsewhere to the target, as with a mouse."], "source": "Week 3 · PDF p. 5", "topic": "Device taxonomy"}, {"id": "w3-s03", "type": "short", "group": "w3", "prompt": "What distinguishes binary from analog input?", "answer": ["Binary input supplies two states, such as pressed or not pressed.", "Analog input supplies a range of values, even if transmitted digitally."], "source": "Week 3 · PDF p. 6", "topic": "Device taxonomy"}, {"id": "w3-s04", "type": "short", "group": "w3", "prompt": "Explain why a mouse and joystick suit different tasks.", "answer": ["A mouse supports precise relative pointing without automatic return to centre.", "A joystick’s centred tilt supports direction and rate control for continuous movement."], "source": "Week 3 · PDF pp. 11–16", "topic": "Devices"}, {"id": "w3-s05", "type": "short", "group": "w3", "prompt": "Why can high-resolution phone screens still have poor touch usability?", "answer": ["Pixel resolution does not guarantee that controls are physically large enough.", "Small targets and finger occlusion can still produce selection errors."], "source": "Week 3 · PDF pp. 48–52", "topic": "Mobile input"}, {"id": "w3-s06", "type": "short", "group": "w3", "prompt": "Distinguish accelerometers from gyroscopes.", "answer": ["An accelerometer measures acceleration, including gravity-related readings.", "A gyroscope measures angular velocity, the rate of rotation."], "source": "Week 3 · PDF pp. 18–19", "topic": "Sensors"}, {"id": "w3-s07", "type": "short", "group": "w3", "prompt": "Why does estimating position from acceleration drift?", "answer": ["Measurement noise accumulates when acceleration is integrated into velocity and position.", "Other sensor references can help reduce the resulting error."], "source": "Week 3 · PDF pp. 18–23", "topic": "Sensors"}, {"id": "w3-s08", "type": "short", "group": "w3", "prompt": "Explain sensor fusion with one example.", "answer": ["Sensor fusion combines readings to estimate information more reliably.", "Orientation can use accelerometer, gyroscope and magnetometer data together."], "source": "Week 3 · PDF p. 23", "topic": "Sensors"}, {"id": "w3-s09", "type": "short", "group": "w3", "prompt": "What are six degrees of freedom?", "answer": ["They include movement along three spatial axes.", "They also include rotation around those three axes."], "source": "Week 3 · PDF p. 24", "topic": "Tracking"}, {"id": "w3-s10", "type": "short", "group": "w3", "prompt": "Give two VR design concerns and an implication.", "answer": ["Motion sickness and physical injury risks affect comfortable, safe use.", "Adapt interaction and feedback to body movement and the surrounding space."], "source": "Week 3 · PDF pp. 31–34", "topic": "VR"}, {"id": "w3-s11", "type": "short", "group": "w3", "prompt": "Why use event-based updates rather than continuous polling on mobile?", "answer": ["Repeated polling creates unnecessary processing and wake-ups.", "Event-based updates can help keep the processor idle and conserve energy."], "source": "Week 3 · PDF pp. 46–47", "topic": "Mobile constraints"}, {"id": "w3-s12", "type": "short", "group": "w3", "prompt": "Why is mobile design more than resizing a desktop interface?", "answer": ["Mobile use differs in touch input, context, resources and short-session expectations.", "Prioritize common tasks, reduce typing and adapt controls to the available space."], "source": "Week 3 · PDF pp. 41–65", "topic": "Mobile constraints"}, {"id": "w4-s01", "type": "short", "group": "w4", "prompt": "Distinguish functional and non-functional requirements.", "answer": ["Functional requirements state what the system should do.", "Non-functional requirements set qualities or constraints, such as response time."], "source": "Week 4 · PDF p. 17", "topic": "Requirements"}, {"id": "w4-s02", "type": "short", "group": "w4", "prompt": "Name the three main categories of user requirements.", "answer": ["Identify user characteristics and user/business goals.", "Describe the physical, social, organizational and cultural context of use."], "source": "Week 4 · PDF pp. 15–18", "topic": "Requirements"}, {"id": "w4-s03", "type": "short", "group": "w4", "prompt": "Explain the value of asking why a user requests a feature.", "answer": ["A feature request may describe one solution rather than the underlying goal.", "Understanding the goal lets designers compare alternative ways to support it."], "source": "Week 4 · PDF pp. 23–26", "topic": "Requirements"}, {"id": "w4-s04", "type": "short", "group": "w4", "prompt": "Why choose a semi-structured interview?", "answer": ["Prepared questions cover important topics consistently.", "Flexible follow-up explores unexpected details and reasons."], "source": "Week 4 · PDF pp. 30–33", "topic": "Interviews"}, {"id": "w4-s05", "type": "short", "group": "w4", "prompt": "Give one benefit and one limitation of think-aloud.", "answer": ["It reveals users’ beliefs, goals and reasons during a task.", "Speaking can feel unnatural and change task performance."], "source": "Week 4 · PDF p. 49", "topic": "Observation"}, {"id": "w4-s06", "type": "short", "group": "w4", "prompt": "List the four contextual inquiry principles.", "answer": ["Context and partnership: study actual work collaboratively.", "Interpretation and focus: clarify meaning together while staying on the research question."], "source": "Week 4 · PDF pp. 55–56", "topic": "Contextual inquiry"}, {"id": "w4-s07", "type": "short", "group": "w4", "prompt": "Explain triangulation.", "answer": ["Triangulation combines methods or data sources to investigate the same issue.", "Agreement supports findings; disagreement identifies questions needing further investigation."], "source": "Week 4 · PDF p. 61", "topic": "Research design"}, {"id": "w4-s08", "type": "short", "group": "w4", "prompt": "What is wrong with “Was the interface clear and fast?”", "answer": ["It asks about two qualities in one answer, making the result ambiguous.", "Ask separately about clarity and speed using neutral wording."], "source": "Week 4 · PDF pp. 33, 39–43", "topic": "Bias"}, {"id": "w4-s09", "type": "short", "group": "w4", "prompt": "What makes a persona useful and credible?", "answer": ["It synthesizes meaningful user characteristics and goals from actual research.", "It represents a relevant user group without idealizing them to fit the design."], "source": "Week 4 · PDF p. 66", "topic": "Personas"}, {"id": "w4-s10", "type": "short", "group": "w4", "prompt": "Distinguish scenarios from use cases.", "answer": ["A scenario is one concrete narrative about activity in context.", "A use case structures actor–system interaction, including conditions and alternative paths."], "source": "Week 4 · PDF pp. 68–75", "topic": "Models"}, {"id": "w4-s11", "type": "short", "group": "w4", "prompt": "Explain HTA and why it needs a plan.", "answer": ["HTA breaks an observable goal-directed activity into tasks and subtasks.", "Plans specify order, conditions and repetition; stop decomposing when further detail has little value."], "source": "Week 4 · PDF pp. 77–80", "topic": "HTA"}, {"id": "w4-s12", "type": "short", "group": "w4", "prompt": "How does a state diagram differ from a task hierarchy?", "answer": ["A state diagram represents system conditions and transitions between them.", "A task hierarchy represents the structure of the user’s activity."], "source": "Week 4 · PDF pp. 77–82", "topic": "State diagrams"}, {"id": "project-s01", "type": "short", "group": "project", "prompt": "What must the walkthrough demonstrate about the conceptual model?", "answer": ["Explain the core concepts, relationships and relevant metaphors.", "Use prototype callouts to show consistency, feedback and constraints."], "source": "Walkthrough brief · Conceptual model", "topic": "Assignment scope"}, {"id": "project-s02", "type": "short", "group": "project", "prompt": "What should the audience questionnaire contain?", "answer": ["At most seven closed-ended and two open-ended questions about the prototype.", "Build it in Google Forms and include its link with the submission."], "source": "Walkthrough brief · Questionnaire", "topic": "Questionnaire"}, {"id": "project-s03", "type": "short", "group": "project", "prompt": "Why distinguish findings from assumptions in the nutrition project?", "answer": ["Proposed users and features are hypotheses until evidence supports them.", "Use interviews and observed tasks to validate needs before claiming improvements."], "source": "Project outline + Week 4 · PDF pp. 20–26", "topic": "Design evidence"}, {"id": "project-s04", "type": "short", "group": "project", "prompt": "Outline one complex task for your nutrition-app prototype.", "answer": ["Request a meal suggestion, inspect it, and swap an unavailable ingredient.", "Save the adjusted meal to a plan and generate its shopping list."], "source": "Idea screenshot + proposed project outline", "topic": "Nutrition concept"}, {"id": "extra-s01", "type": "short", "group": "extra", "prompt": "Name the four cognitive walkthrough questions in the supplied photos.", "answer": ["Will the user pursue the right goal and notice the needed action?", "Will they connect the action to the goal and understand the feedback?"], "source": "Other professor · IMG_4845.JPG / IMG_4846.JPG", "topic": "Cognitive walkthrough"}, {"id": "extra-s02", "type": "short", "group": "extra", "prompt": "Evaluate David’s failed booking in the supplied walkthrough photo.", "answer": ["He wants to book, but hidden prerequisites and options make the action sequence unclear.", "Unexplained disabled controls and missing errors leave feedback inadequate."], "source": "Other professor · IMG_4846.JPG", "topic": "Cognitive walkthrough"}, {"id": "extra-s03", "type": "short", "group": "extra", "prompt": "Compute the sample KLM time: 3 P, 3 K, 1 M, 1 R; P=1.1, K=.2, M=1.35, R=.02 seconds.", "answer": ["T = 3(1.1) + 3(0.2) + 1.35 + 0.02.", "T = 5.27 seconds, assuming exactly the stated operators and one response interval."], "source": "Other professor · IMG_4843.JPG", "topic": "KLM"}, {"id": "extra-s04", "type": "short", "group": "extra", "prompt": "In the sample, why does a bar chart suit category comparison?", "answer": ["Bars display values for distinct categories side by side.", "Their lengths make differences between categories easy to compare."], "source": "Other professor · IMG_4848.JPG", "topic": "Evaluation extras"}, {"id": "context-s01", "type": "short", "group": "context", "prompt": "What is the excluded constructivist view of perception?", "answer": ["Perception combines information from the environment with previously stored knowledge.", "The experienced world is an interpretation, rather than a simple camera copy."], "source": "Week 2 · PDF pp. 66–70 · Not on test", "topic": "Constructivism"}, {"id": "context-s02", "type": "short", "group": "context", "prompt": "Give two sound-localization cues from the excluded slide.", "answer": ["Differences in sound level between ears provide one cue.", "Differences in arrival time between ears provide another."], "source": "Week 2 · PDF p. 86 · Not on test", "topic": "Sound localization"}]};
